// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange - Mock contexts (we didn't vote for these, but here they are)
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: [{ id: '1', name: 'Holy Grail', price: 999.99 }],
    total: 999.99,
    clearCart: mockClearCart,
  }),
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment }),
}));

describe('Checkout - The Quest for Valid Orders', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'GRAIL-001' });
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('should complete entire checkout journey from shipping to confirmation', async () => {
      // Arrange
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Act - Shipping step
      await user.type(screen.getByRole('textbox', { name: /street/i }), '742 Camelot Way');
      await user.type(screen.getByRole('textbox', { name: /city/i }), 'Camelot');
      await user.selectOptions(screen.getByRole('combobox', { name: /state/i }), 'CA');
      await user.type(screen.getByRole('textbox', { name: /zip/i }), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Act - Payment step
      await user.type(screen.getByRole('textbox', { name: /card number/i }), '4111111111111111');
      await user.type(screen.getByRole('textbox', { name: /expiry/i }), '12/25');
      await user.type(screen.getByRole('textbox', { name: /cvv/i }), '123');
      await user.type(screen.getByRole('textbox', { name: /name on card/i }), 'Arthur Pendragon');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Act - Review step
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert
      await waitFor(() => {
        expect(screen.getByRole('status')).toHaveTextContent('GRAIL-001');
      });
      expect(onComplete).toHaveBeenCalledWith('GRAIL-001');
      expect(mockClearCart).toHaveBeenCalled();
    });
  });

  describe('Form Validation - Tis But a Scratch', () => {
    it('should display error when street address is empty', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
    });

    it('should display error for invalid ZIP code', async () => {
      render(<Checkout />);
      await user.type(screen.getByRole('textbox', { name: /zip/i }), 'NI!');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Edge Cases - Silly Places', () => {
    it('should show empty cart message when no items', () => {
      vi.doMock('./CartContext', () => ({ useCart: () => ({ items: [], total: 0 }) }));
      render(<Checkout />);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Accessibility - Knights Who Say A11y', () => {
    it('should have no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });
  });
});
